#!/usr/bin/env bun
/**
 * The Lua 5.1 builds of the two Luau modules the host embeds, written next to the other generated files:
 *
 *   types/generated/ui.lua       <- types/generated/ui.luau    (`require("@agentos/ui")`)
 *   types/generated/prelude.lua  <- lua/prelude.luau           (the Luau standard-library polyfills)
 *
 *   bun scripts/codegen-lua.ts          write them (part of `bun run codegen`, after the Rust generator wrote ui.luau)
 *   bun scripts/codegen-lua.ts --check  exit 1 when one is missing or stale (part of `bun run codegen:check`)
 *
 * Needs the pinned darklua (see scripts/lua51.ts). Never edit the outputs by hand.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { requireDarklua, root, toLua51 } from './lua51'

const TARGETS = [
  { from: 'types/generated/ui.luau', to: 'types/generated/ui.lua' },
  { from: 'lua/prelude.luau', to: 'types/generated/prelude.lua' }
]

const mode = process.argv[2]
if (mode !== undefined && mode !== '--check') {
  console.error('usage: bun scripts/codegen-lua.ts [--check]')
  process.exit(2)
}

const darklua = requireDarklua()
const stale: string[] = []
for (const { from, to } of TARGETS) {
  const header = `-- GENERATED by scripts/codegen-lua.ts from ${from} (darklua, Lua 5.1). Do not edit.`
  const lua = toLua51(darklua, join(root, from))
  // The build keeps every line where it was (.darklua.json: retain_lines), so an error at `ui.lua:N` is line N of
  // ui.luau. The header goes on the first line, which is the (removed) `--!strict` comment: never on a line of code.
  const contents = lua.startsWith('\n') ? header + lua : `${header}\n${lua}`
  const target = join(root, to)
  if (mode === '--check') {
    if (!existsSync(target) || readFileSync(target, 'utf8') !== contents) stale.push(to)
  } else {
    writeFileSync(target, contents)
    console.log(`wrote ${to}`)
  }
}

if (mode === '--check') {
  if (stale.length > 0) {
    console.error('codegen:check FAILED: the Lua 5.1 builds are stale:')
    for (const path of stale) console.error(`  ${path}`)
    console.error('run `bun run codegen` and commit the result')
    process.exit(1)
  }
  console.log(`codegen:check OK (${TARGETS.length} Lua 5.1 builds up to date)`)
}
